// Home needs summaries, never the report body or provider operation journal.
export type HomeRun = {
  id: string;
  idea: string;
  category: IdeaBrief["category"];
  status: RunState["status"];
  stage: RunStage;
  createdAt: string;
  parentId: string | null;
