+import { db } from "./store";
+import { operationContext } from "./operation-context";
+
+function context() { const c = operationContext.getStore(); if (!c?.owner) throw new Error("UNAUTHENTICATED"); return c; }
+function ceiling(phase: string) {
+  return { cents: phase.startsWith("crust-search-") || phase === "crust-fetch" ? 0 : phase === "crust-plan" || phase === "crust-select" ? 5 : phase === "cfo" ? 0 : 25,
+    credits: phase.startsWith("crust-search-") ? 1000 : phase === "crust-fetch" ? 3000 : 0 };
+}
+export async function agentOperation(id: string, phase: string) {
+  const { owner } = context();
+  const rows = await db()`select o.* from provider_operations o join runs r on r.id=o.run_id where r.id=${id} and r.owner_id=${owner} and o.phase=${phase}`;
+  return rows[0];
+}
+export async function claimAgentOperation(id: string, phase: string) {
+  const { owner, revision, lease } = context(), cap = ceiling(phase);
+  const rows = await db()`with eligible as (
+    select * from runs where id=${id} and owner_id=${owner} and mode='autonomous' and status in ('queued','running')
+      and lease_token=${lease} and lease_until>now() and deadline_at>now() for update
+  ), funded as (
+    update runs set operation_budget_cents=operation_budget_cents+${cap.cents},operation_budget_credits=operation_budget_credits+${cap.credits}
