import { Inngest, NonRetriableError } from "inngest";
import { internalRun, progress, finishRun, failRun,reserveCrustSlot } from "./store";
import { startResponse, pollResponse, discoveryParams, verificationParams, compositionParams, mergeEvidence, assembleReport, type ResearchEvidence } from "./research";
import { modelIdeaWithCfo } from "./cfo";
import { sponsoredComposition } from "./sponsored-model";
import { checkCrustAccount,planCrustResearch,searchCrust,selectCrustPages,fetchCrustPages } from "./crustdata";
import { crustEvidence,type SearchReceipt } from "./crustdata-parse";
import { CRUST_CREDITS } from "./research-provider";
import { advanceAgent } from "./agent-worker";
import { acknowledgeWake, pendingAgentWakes, stalledAgentPointers, rescueAgent, autonomousEnabled, agentSchemaReady, type Wake } from "./agent-store";
export const inngest = new Inngest({ id: "hunchlane", checkpointing: { maxRuntime: "40s" } });
export async function dispatchAgentWake(wake: Wake) {
  await inngest.send({ id: wake.id, name: "hunchlane/agent.wake", data: { runId: wake.runId, ownerId: wake.ownerId } });
  await acknowledgeWake(wake);
}
export const agentFunction = inngest.createFunction({
  id: "continuous-agent", triggers: { event: "hunchlane/agent.wake" },
  concurrency: [{ limit: 2 }, { limit: 1, key: "event.data.ownerId" }], retries: 3,
}, async ({ event, step }) => {
  const { runId, ownerId } = event.data;
  if (typeof ownerId !== "string" || !ownerId.trim() || typeof runId !== "string") throw new NonRetriableError("Invalid run identity");
  const wake = await step.run("advance", () => advanceAgent(runId, ownerId));
  if (!wake) return { finished: true };
  await step.sleepUntil("next-attempt", wake.availableAt);
  await step.sendEvent("dispatch", { id: wake.id, name: "hunchlane/agent.wake", data: { runId, ownerId } });
  await step.run("acknowledge", () => acknowledgeWake(wake));
  return { scheduled: true };
});
export const agentRecoveryFunction = inngest.createFunction({
  id: "continuous-agent-recovery", triggers: { cron: "* * * * *" }, concurrency: { limit: 1 }, retries: 3,
}, async ({ step }) => {
  // Continue already admitted runs even after the admission feature flag is switched off.
  if (!process.env.DATABASE_URL) return { dispatched: 0 };
  if(!await step.run("schema-ready",agentSchemaReady)) return {dispatched:0};
  const pointers = await step.run("stalled-identities", stalledAgentPointers);
  for (const pointer of pointers) await step.run(`rescue-${pointer.id}`, () => rescueAgent(pointer.id, pointer.owner));
  const wakes = await step.run("outbox", pendingAgentWakes);
  for (const wake of wakes) {
    await step.sendEvent(`dispatch-${wake.id}`, { id: wake.id, name: "hunchlane/agent.wake", data: { runId: wake.runId, ownerId: wake.ownerId } });
    await step.run(`ack-${wake.id}`, () => acknowledgeWake(wake));
  }
  return { dispatched: wakes.length, admissionEnabled: autonomousEnabled() };
});
export const researchFunction = inngest.createFunction({
  id: "research-idea", triggers: { event: "hunchlane/research.created" },
  concurrency: [{ limit: 2 }, { limit: 1, key: "event.data.ownerId" }], retries: 1,
}, async ({ event, step }) => {
  const ownerId = event.data.ownerId;
  if (typeof ownerId !== "string" || !ownerId.trim()) throw new NonRetriableError("Research owner is required");
  const runId = String(event.data.runId);
  const run = await step.run("load-run", () => internalRun(runId, ownerId));
  if(run.mode === "autonomous") throw new NonRetriableError("Continuous runs use the continuous worker");
  if (run.status === "complete") return { runId, complete: true };
  const parent = run.parentId ? await step.run("load-parent", () => internalRun(run.parentId!, ownerId)) : null;
  const previous = parent?.report || null;
  try {
    let evidence:ResearchEvidence;
    await step.run("discovering", () => progress(runId,"discovering"));
    if(run.provider === "crustdata"){
      await step.run("crust-account",()=>checkCrustAccount(CRUST_CREDITS[previous?"refinement":"full"]));
      const plan=await step.run("crust-plan",()=>planCrustResearch(runId,run.brief,previous));
      const searches:SearchReceipt[]=[];
      for(let i=0;i<plan.queries.length;i++){
        const slot=await step.run(`crust-search-slot-${i}`,()=>reserveCrustSlot());
        await step.sleepUntil(`crust-search-wait-${i}`,slot);
        searches.push(await step.run(`crust-search-${i}`,()=>searchCrust(runId,i,plan.queries[i])));
      }
      await step.run("verifying",()=>progress(runId,"verifying"));
      const urls=await step.run("crust-select",()=>selectCrustPages(runId,run.brief,searches));
      if(urls.length){const slot=await step.run("crust-fetch-slot",()=>reserveCrustSlot());await step.sleepUntil("crust-fetch-wait",slot);}
      const pages=await step.run("crust-fetch",()=>fetchCrustPages(runId,urls));
      evidence=crustEvidence(searches,pages,urls);
    }else{
    const discoveryId = await step.run("start-discovery", () => startResponse(runId,"discovery",discoveryParams(run.brief,previous)));
    let discovery: unknown = null;
    for (let i=0; i<60 && !discovery; i++) {
      discovery = await step.run(`poll-discovery-${i}`, () => pollResponse(runId,"discovery",discoveryId));
      if (!discovery) await step.sleep(`wait-discovery-${i}`,"5s");
    }
    if (!discovery) throw new Error("RESEARCH_TIMEOUT");
    await step.run("verifying", () => progress(runId,"verifying"));
    const verificationId = await step.run("start-verification", () => startResponse(runId,"verification",verificationParams(run.brief,discovery as ResearchEvidence,!!previous)));
    let verification: unknown = null;
    for (let i=0; i<60 && !verification; i++) {
      verification = await step.run(`poll-verification-${i}`, () => pollResponse(runId,"verification",verificationId));
      if (!verification) await step.sleep(`wait-verification-${i}`,"5s");
    }
    if (!verification) throw new Error("RESEARCH_TIMEOUT");
    evidence = mergeEvidence(discovery as ResearchEvidence,verification as ResearchEvidence);
    }
    await step.run("composing", () => progress(runId,"composing"));
    let content: unknown = null;
    if(process.env.LITELLM_API_KEY){
      content=await step.run("sponsored-composition",()=>sponsoredComposition(runId,run.brief,evidence,previous));
    }else{
      const contentId = await step.run("start-composition", () => startResponse(runId,"composition",compositionParams(run.brief,evidence,previous)));
      for (let i=0; i<60 && !content; i++) {
        content = await step.run(`poll-composition-${i}`, () => pollResponse(runId,"composition",contentId));
        if (!content) await step.sleep(`wait-composition-${i}`,"5s");
      }
    }
    if (!content) throw new Error("RESEARCH_TIMEOUT");
    const report = await step.run("validate-evidence", async () => assembleReport(content,evidence,run.brief,previous));
    await step.run("finances", () => progress(runId,"finances"));
    const finance = await step.run("cfo-model", () => modelIdeaWithCfo(runId,run.brief));
    await step.run("save-report", () => finishRun(runId,{ ...report,finance }));
    return { runId, complete: true };
  } catch (error) {
    const uncertain = error instanceof Error && error.message === "RECONCILIATION_REQUIRED";
    const invalidEvidence = error instanceof Error && error.name === "EvidenceValidationError";
    await step.run("save-error", () => failRun(runId,uncertain ? "A provider request needs a check before retrying. Your progress is saved." : invalidEvidence ? "The saved report did not pass its source checks. Your research is saved. Repeating Resume will reuse that response; it needs correction before it can be displayed." : "Research paused before the report was ready. Your progress is saved; you can retry from the last checkpoint."));
    throw new NonRetriableError(uncertain ? "Provider reconciliation required" : "Research paused", { cause: error });
  }
});

import { createHash, randomUUID } from "node:crypto";
import { AGENT_LIMITS, openingConversation, type AgentCursor, type AgentMessageInput } from "@/core/agent";
import { RESERVATIONS } from "@/core/budget";
import type { IdeaBrief, ResearchReport, RunStage } from "@/core/types";
import { db, ownedRun } from "./store";
import { CRUST_CREDITS, type ResearchProvider } from "./research-provider";

export function autonomousEnabled() { return process.env.HUNCHLANE_AUTONOMOUS_FLOW === "1"; }
export async function agentSchemaReady() { const rows=await db()`select to_regclass('public.agent_outbox') is not null as ready`; return Boolean(rows[0]?.ready); }
export type Wake = { id: string; runId: string; ownerId: string; availableAt: string };
export function agentSubmissionHash(brief: IdeaBrief, parentId: string | null) { return createHash("sha256").update(JSON.stringify({brief,parentId})).digest("hex"); }
export async function matchesAgentSubmission(id: string, owner: string, brief: IdeaBrief, parentId: string | null) {
  const rows=await db()`select id from runs where id=${id} and owner_id=${owner} and mode='autonomous' and submission_hash=${agentSubmissionHash(brief,parentId)}`;return rows.length>0;
}
export async function createAgentRun(id: string, owner: string, brief: IdeaBrief, parentId: string | null, provider: ResearchProvider) {
  if (!owner) throw new Error("UNAUTHENTICATED");
  const existing = await ownedRun(id, owner);
  if (existing) {
    if (!await matchesAgentSubmission(id,owner,brief,parentId)) throw new Error("SUBMISSION_CONFLICT");
    return existing;
  }
  if (parentId) { const parent = await ownedRun(parentId, owner); if (!parent?.report || parent.parentId) throw new Error("REFINEMENT_NOT_ALLOWED"); }
  const now = new Date().toISOString(), kind = parentId ? "refinement" : "full", cents = RESERVATIONS[kind], credits = provider === "crustdata" ? CRUST_CREDITS[kind] * 1000 : 0;
  const conversation = openingConversation(brief, now);
  // Admission, reservation and first dispatch intent are one transaction, including quota constraints.
  await db()`with reserve as (
    update budgets set allocated_cents=allocated_cents+${cents},credit_allocated_milli=credit_allocated_milli+${credits}
    where id='research' and allocated_cents+${cents}<=limit_cents and credit_allocated_milli+${credits}<=credit_limit_milli returning id
  ), created as (
    insert into runs(id,owner_id,kind,brief,parent_id,reservation_cents,provider,credit_reservation_milli,mode,conversation,deadline_at,submission_hash)
    select ${id},${owner},${kind},${JSON.stringify(brief)}::jsonb,${parentId},${cents},${provider},${credits},'autonomous',${JSON.stringify(conversation)}::jsonb,
      ${now}::timestamptz+interval '20 minutes',${agentSubmissionHash(brief,parentId)} from reserve returning id,owner_id
  ) insert into agent_outbox(id,run_id,owner_id) select ${`agent-${id}-0`},id,owner_id from created`;
  const run = await ownedRun(id, owner);
  if (!run) throw new Error("BUDGET_EXHAUSTED");
  return run;
}

export async function appendAgentMessage(id: string, owner: string, input: AgentMessageInput) {
  if (!owner) throw new Error("UNAUTHENTICATED");
  const run = await ownedRun(id, owner); if (!run?.agent) throw new Error("RUN_NOT_FOUND");
  const old = run.agent.conversation.messages.find(m => m.id === input.id);
  if (old) { if (old.text !== input.text) throw new Error("SUBMISSION_CONFLICT"); return run; }
  if (input.questionId && !run.agent.conversation.questions.some(q => q.id === input.questionId)) throw new Error("INVALID_QUESTION");
  const key = input.questionId || `context-${input.id}`, now = new Date().toISOString();
  const rows = await db()`with current as (
    select * from runs where id=${id} and owner_id=${owner} and mode='autonomous' for update
  ) update runs r set conversation=jsonb_set(jsonb_set(r.conversation,'{messages}',r.conversation->'messages'||jsonb_build_array(
    jsonb_build_object('id',${input.id}::text,'role','user','text',${input.text}::text,'createdAt',${now}::text,
      'followUp',r.locked_revision is not null or r.status in ('complete','failed')))), '{questions}',
    (select coalesce(jsonb_agg(case when q->>'id'=${input.questionId || ""} then q||jsonb_build_object('answer',${input.text}::text) else q end),'[]'::jsonb) from jsonb_array_elements(r.conversation->'questions') q)),
    brief=case when r.locked_revision is null and r.status in ('queued','running') and not ${Boolean(input.useJudgment)} then
      jsonb_set(case when ${input.questionId === "audience"} then jsonb_set(r.brief,'{audience}',to_jsonb(${input.text.slice(0, 300)}::text)) else r.brief end,
        '{answers}',coalesce(r.brief->'answers','{}'::jsonb)||jsonb_build_object(${key}::text,${input.text.slice(0, 500)}::text)) else r.brief end,
    brief_revision=r.brief_revision+case when r.locked_revision is null and r.status in ('queued','running') and not ${Boolean(input.useJudgment)} then 1 else 0 end
    from current c where r.id=c.id and r.owner_id=${owner}
      and jsonb_array_length(r.conversation->'messages')<50
      and not exists(select 1 from jsonb_array_elements(r.conversation->'messages') m where m->>'id'=${input.id}) returning r.id`;
  if (!rows.length) {
    const saved = await ownedRun(id, owner);
    if (!saved?.agent?.conversation.messages.some(m => m.id === input.id && m.text === input.text)) throw new Error("CONVERSATION_LIMIT");
  }
  return ownedRun(id, owner);
}

export async function acquireAgentLease(id: string, owner: string) {
  if (!owner) throw new Error("UNAUTHENTICATED");
  const lease = randomUUID();
  const rows = await db()`update runs set lease_token=${lease},lease_until=now()+interval '90 seconds',status='running'
    where id=${id} and owner_id=${owner} and mode='autonomous' and status in ('queued','running')
      and next_attempt_at<=now() and (lease_until is null or lease_until<now()) returning id`;
  return rows.length ? lease : null;
}
export async function freezeAgentBrief(id: string, owner: string, lease: string) {
  await db()`update runs set locked_revision=brief_revision,final_brief=brief
    where id=${id} and owner_id=${owner} and lease_token=${lease} and locked_revision is null`;
  return ownedRun(id, owner);
}
export async function scheduleAgent(id: string, owner: string, lease: string, cursor: AgentCursor, stage: RunStage,
  seconds = 0, recovery: "working" | "recovering" | "reconciling" = "working", activity?: string, resetAttempts = true): Promise<Wake | null> {
  const at = new Date(Date.now() + seconds * 1000).toISOString();
  const entry = activity ? [{ id: `${cursor}-${recovery}`, text: activity, createdAt: new Date().toISOString() }] : [];
  const rows = await db()`with updated as (
    update runs set agent_cursor=${cursor},stage=${stage},next_attempt_at=least(${at}::timestamptz,deadline_at),recovery=${recovery},
      recovery_attempts=case when ${resetAttempts} then 0 else recovery_attempts+1 end,
      wake_sequence=wake_sequence+1,lease_token=null,lease_until=null,
      conversation=case when ${Boolean(activity)} and not exists(select 1 from jsonb_array_elements(conversation->'activity') a where a->>'id'=${`${cursor}-${recovery}`})
        then jsonb_set(conversation,'{activity}',conversation->'activity'||${JSON.stringify(entry)}::jsonb) else conversation end
    where id=${id} and owner_id=${owner} and lease_token=${lease} and status in ('queued','running') returning *
  ) insert into agent_outbox(id,run_id,owner_id,available_at)
    select 'agent-'||id||'-'||wake_sequence,id,owner_id,next_attempt_at from updated returning *`;
  return rows[0] ? { id: String(rows[0].id), runId: id, ownerId: owner, availableAt: new Date(String(rows[0].available_at)).toISOString() } : null;
}
export async function finishAgent(id: string, owner: string, lease: string, report: ResearchReport | null) {
