  const model=process.env.LITELLM_MODEL||"claude-sonnet-4.6";
  if(!allowed.has(model))throw new Error("UNSUPPORTED_SPONSORED_MODEL");
  if(!process.env.LITELLM_API_KEY)throw new Error("INTEGRATIONS_NOT_READY");
