import { Inngest, NonRetriableError } from "inngest";
import {
  internalRun,
  progress,
  finishRun,
  failRun,
  reserveCrustSlot,
} from "./store";
import {
  startResponse,
  pollResponse,
  discoveryParams,
  verificationParams,
  compositionParams,
  mergeEvidence,
  assembleReport,
  type ResearchEvidence,
} from "./research";
import { modelIdeaWithCfo } from "./cfo";
import { sponsoredComposition } from "./sponsored-model";
import {
  checkCrustAccount,
  planCrustResearch,
  searchCrust,
  selectCrustPages,
  fetchCrustPages,
} from "./crustdata";
import { crustEvidence, type SearchReceipt } from "./crustdata-parse";
import { CRUST_CREDITS } from "./research-provider";
import { advanceAgent } from "./agent-worker";
import {
  acknowledgeWake,
  pendingAgentWakes,
  stalledAgentPointers,
  rescueAgent,
  autonomousEnabled,
  agentSchemaReady,
  type Wake,
} from "./agent-store";
export const inngest = new Inngest({
  id: "hunchlane",
  checkpointing: { maxRuntime: "40s" },
});
export async function dispatchAgentWake(wake: Wake) {
  await inngest.send({
    id: wake.id,
    name: "hunchlane/agent.wake",
    data: { runId: wake.runId, ownerId: wake.ownerId },
  });
  await acknowledgeWake(wake);
}
export const agentFunction = inngest.createFunction(
  {
    id: "continuous-agent",
    triggers: { event: "hunchlane/agent.wake" },
    concurrency: [{ limit: 2 }, { limit: 1, key: "event.data.ownerId" }],
    retries: 3,
  },
  async ({ event, step }) => {
    const { runId, ownerId } = event.data;
    if (
      typeof ownerId !== "string" ||
      !ownerId.trim() ||
      typeof runId !== "string"
    )
      throw new NonRetriableError("Invalid run identity");
    const wake = await step.run("advance", () => advanceAgent(runId, ownerId));
    if (!wake) return { finished: true };
    await step.sleepUntil("next-attempt", wake.availableAt);
    await step.sendEvent("dispatch", {
      id: wake.id,
      name: "hunchlane/agent.wake",
      data: { runId, ownerId },
    });
    await step.run("acknowledge", () => acknowledgeWake(wake));
    return { scheduled: true };
  }
);
export const agentRecoveryFunction = inngest.createFunction(
  {
    id: "continuous-agent-recovery",
    triggers: { cron: "* * * * *" },
    concurrency: { limit: 1 },
    retries: 3,
  },
  async ({ step }) => {
    // Continue already admitted runs even after the admission feature flag is switched off.
    if (!process.env.DATABASE_URL) return { dispatched: 0 };
    if (!(await step.run("schema-ready", agentSchemaReady)))
      return { dispatched: 0 };
    const pointers = await step.run("stalled-identities", stalledAgentPointers);
    for (const pointer of pointers)
      await step.run(`rescue-${pointer.id}`, () =>
        rescueAgent(pointer.id, pointer.owner)
      );
    const wakes = await step.run("outbox", pendingAgentWakes);
    for (const wake of wakes) {
      await step.sendEvent(`dispatch-${wake.id}`, {
        id: wake.id,
        name: "hunchlane/agent.wake",
        data: { runId: wake.runId, ownerId: wake.ownerId },
      });
      await step.run(`ack-${wake.id}`, () => acknowledgeWake(wake));
    }
    return { dispatched: wakes.length, admissionEnabled: autonomousEnabled() };
  }
);
export const researchFunction = inngest.createFunction(
  {
    id: "research-idea",
    triggers: { event: "hunchlane/research.created" },
    concurrency: [{ limit: 2 }, { limit: 1, key: "event.data.ownerId" }],
    retries: 1,
  },
  async ({ event, step }) => {
    const ownerId = event.data.ownerId;
    if (typeof ownerId !== "string" || !ownerId.trim())
      throw new NonRetriableError("Research owner is required");
    const runId = String(event.data.runId);
    const run = await step.run("load-run", () => internalRun(runId, ownerId));
    if (run.mode === "autonomous")
      throw new NonRetriableError("Continuous runs use the continuous worker");
    if (run.status === "complete") return { runId, complete: true };
    const parent = run.parentId
      ? await step.run("load-parent", () => internalRun(run.parentId!, ownerId))
      : null;
    const previous = parent?.report || null;
    try {
      let evidence: ResearchEvidence;
      await step.run("discovering", () => progress(runId, "discovering"));
      if (run.provider === "crustdata") {
        await step.run("crust-account", () =>
          checkCrustAccount(CRUST_CREDITS[previous ? "refinement" : "full"])
        );
        const plan = await step.run("crust-plan", () =>
          planCrustResearch(runId, run.brief, previous)
        );
        const searches: SearchReceipt[] = [];
        for (let i = 0; i < plan.queries.length; i++) {
          const slot = await step.run(`crust-search-slot-${i}`, () =>
            reserveCrustSlot()
          );
