import { z } from 'zod';
import { IdeaBriefSchema, type IdeaBrief } from './types';
export const DRAFT_KEY = 'hunchlane.idea-draft.v2';
export const LEGACY_DRAFT_KEY = 'hunchlane.idea-draft.v1';
export const emptyBrief: IdeaBrief = {
  idea: '',
  category: 'software',
  audience: '',
  location: '',
  answers: {}
};
export const IntakeReplySchema = z.object({
  message: z.string().min(1).max(700),
  question: z.string().max(180),
  suggestions: z.array(z.string().min(1).max(150)).max(3),
  ready: z.boolean()
});
export type IntakeReply = z.infer<typeof IntakeReplySchema>;
export const DraftSchema = z.object({
  version: z.literal(2),
  brief: IdeaBriefSchema.extend({
    idea: z.string().max(3000)
  }),
  step: z.enum(['describe', 'context', 'review']),
  messages: z.array(z.object({
    role: z.enum(['user', 'assistant']),
    text: z.string().max(3000)
  })).max(10).default([]),
  reply: IntakeReplySchema.nullable().default(null),
  intakeId: z.string().uuid().nullable().default(null),
  turn: z.number().int().min(0).max(3).default(0),
  pending: z.enum(['intake', 'research']).nullable().default(null),
  requestId: z.string().uuid().nullable().default(null),
  buffer: z.string().max(3000).default('')
});
export type IdeaDraft = z.infer<typeof DraftSchema>;
export function newDraft(): IdeaDraft {
  return DraftSchema.parse({
    version: 2,
    brief: emptyBrief,
    step: 'describe'
  });
}
export function parseDraft(current: string | null, legacy: string | null): IdeaDraft | null {
  try {
    if (current) {
      const parsed = DraftSchema.safeParse(JSON.parse(current));
      if (parsed.success) return parsed.data;
    }
  } catch {}
  try {
    if (legacy) {
      const parsed = IdeaBriefSchema.safeParse(JSON.parse(legacy));
      if (parsed.success) return {
        ...newDraft(),
        brief: parsed.data
      };
    }
  } catch {}
  return null;
}
import { describe, expect, it } from "vitest";
import { homeNext, type HomeRun } from "../src/core/home";
import { sampleReport } from "../src/core/sample";

const report: HomeRun = { id: "report", idea: "An idea", category: "software", status: "complete", stage: "complete", createdAt: "2026-10-09T00:00:00.000Z", parentId: null, title: "Report", hasReport: true };
const active: HomeRun = { ...report, id: "active", status: "running", stage: "verifying", hasReport: false, createdAt: "2026-10-10T00:00:00.000Z" };
describe("home next action", () => {
  it("prioritizes current research, then a device draft, then the latest report", () => {
    expect(homeNext([report, active], sampleReport.brief)).toEqual({ kind: "active", run: active });
    expect(homeNext([report], sampleReport.brief)).toEqual({ kind: "draft", draft: sampleReport.brief });
    expect(homeNext([report], null)).toEqual({ kind: "report", run: report });
  });
  it("uses the newest eligible run without changing input order and keeps paused work recoverable", () => {
    const older = { ...active, id: "older", createdAt: "2026-10-08T00:00:00.000Z" };
    const runs = [older, active];
    expect(homeNext(runs, null)).toEqual({ kind: "active", run: active });
    expect(runs[0]).toBe(older);
    const paused = { ...active, status: "failed" as const };
    expect(homeNext([paused], null)).toEqual({ kind: "paused", run: paused });
    expect(homeNext([], null)).toEqual({ kind: "empty" });
  });
});
