  const root = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const element = root.current;
    if (!element || !("IntersectionObserver" in window)) return;
    const reduced = window.matchMedia("(prefers-reduced-motion: reduce)");
    const narrow = window.matchMedia("(max-width: 760px)");
    const stage = element.querySelector<HTMLElement>("[data-unfold]");
    const reveals = element.querySelectorAll<HTMLElement>("[data-reveal]");
    let frame = 0;
    let stageVisible = false;

    function update() {
      frame = 0;
      if (!stage) return;
      if (reduced.matches || narrow.matches) {
        stage.style.setProperty("--showcase-progress", "1");
        return;
      }
      const top = stage.getBoundingClientRect().top;
      // Unfold within the normal viewport; no pinning or added scroll distance.
      const progress = Math.min(1, Math.max(0, (window.innerHeight * .85 - top) / (window.innerHeight * .65)));
      stage.style.setProperty("--showcase-progress", progress.toFixed(3));
    }

    function schedule() {
      if (!frame && stageVisible && !reduced.matches && !narrow.matches) frame = window.requestAnimationFrame(update);
    }

    function preferenceChanged() {
      if (frame) window.cancelAnimationFrame(frame);
      element?.setAttribute("data-motion", reduced.matches ? "off" : "on");
      if (reduced.matches) reveals.forEach(item => item.setAttribute("data-revealed", ""));
      update();
    }

    const revealObserver = new IntersectionObserver(entries => {
      entries.forEach(entry => {
        if (entry.isIntersecting) {
          entry.target.setAttribute("data-revealed", "");
          revealObserver.unobserve(entry.target);
        }
      });
    }, { threshold: .08 });
    reveals.forEach(item => revealObserver.observe(item));
    const stageObserver = new IntersectionObserver(([entry]) => {
      stageVisible = entry.isIntersecting;
      if (stageVisible) schedule();
    });
    if (stage) stageObserver.observe(stage);
    preferenceChanged();
    window.addEventListener("scroll", schedule, { passive: true });
    window.addEventListener("resize", preferenceChanged);
    reduced.addEventListener("change", preferenceChanged);
    narrow.addEventListener("change", preferenceChanged);

    return () => {
      revealObserver.disconnect();
      stageObserver.disconnect();
      window.cancelAnimationFrame(frame);
      window.removeEventListener("scroll", schedule);
      window.removeEventListener("resize", preferenceChanged);
      reduced.removeEventListener("change", preferenceChanged);
      narrow.removeEventListener("change", preferenceChanged);
      element.removeAttribute("data-motion");
      stage?.style.removeProperty("--showcase-progress");
    };
  }, []);

  return <div ref={root} className="landing-details">{children}</div>;
}"},{"rank":4,"score":21.199,"file_path":"src/app/landing-details.css","start_line":21,"end_line":21,"focus_line":21,"snippet_start_line":21,"snippet_end_line":21,"symbol_start_line":21,"symbol_end_line":21,"language":"CSS","kind":"selector","symbol_id":"gh/NiKHiLkr23/hunchlane:CSS:src/app/landing-details.css:selector:landing-eyebrow","symbol_name":"landing-eyebrow","qualified_name":"landing-eyebrow","signature":"css selector .landing-eyebrow","signals":["path","body","symbol-name"],"snippet":".landing-eyebrow { font-size: 10px; font-weight: 700; letter-spacing: .065em; color: var(--studio-muted); }"},{"rank":5,"score":15.2686,"file_path":"src/app/studio.css","start_line":83,"end_line":83,"focus_line":83,"snippet_start_line":83,"snippet_end_line":83,"symbol_start_line":83,"symbol_end_line":83,"language":"CSS","kind":"selector","symbol_id":"gh/NiKHiLkr23/hunchlane:CSS:src/app/studio.css:selector:studio-landing#sig:b8d699848616c2d0#2","symbol_name":"studio-landing","qualified_name":"studio-landing","signature":"css selector .studio-landing","signals":["body","symbol-name"],"snippet":"  .studio-landing { padding: 0 24px; }"},{"rank":6,"score":18.0219,"file_path":"src/app/landing-details.css","start_line":1,"end_line":2,"focus_line":2,"snippet_start_line":1,"snippet_end_line":2,"symbol_start_line":2,"symbol_end_line":2,"language":"CSS","kind":"selector","symbol_id":"gh/NiKHiLkr23/hunchlane:CSS:src/app/landing-details.css:selector:landing-details","symbol_name":"landing-details","qualified_name":"landing-details","signature":"css selector .landing-details","signals":["path","body","symbol-name"],"snippet":"/* Teal and Depth: landing-only report showcase, benefits and closing. */
